#!/usr/bin/env node
/**
 * Purge identified spam bot accounts and all artifacts/content they generated:
 * - Comments authored by them (and any comments targeting their profiles)
 * - Notifications generated by their activity or addressed to them
 * - Follows initiated by or targeting them
 * - Likes given by them on poems (cleaned via $pull)
 * - The author records themselves
 *
 * DRY-RUN BY DEFAULT. Pass --commit to execute writes.
 *
 * Usage:
 *   node scripts/purge-spam-accounts.js            # Dry run / report only
 *   node scripts/purge-spam-accounts.js --commit   # Execute deletions & cleanup
 */
const path = require('path')
require('dotenv').config({ path: path.resolve(__dirname, '../.env') })
const mongoose = require('mongoose')

// Safety switches required by AGENTS.md before compiling models or connecting
mongoose.set('autoIndex', false)
mongoose.set('autoCreate', false)

const TARGET_USERNAMES = [
  'lunarlibraryy',
  'lyraxo',
  'Elsaeloise',
  'NancyMarkson',
  'lunarlibrary',
  'lunarrr',
  'lyrasays',
  'lyrastatic',
  'lyralilac',
  'akira_artly'
]

async function run () {
  const isCommit = process.argv.includes('--commit')
  const uri = process.env.MONGODB_PRE || process.env.MONGODB

  if (!uri) {
    console.error('No MONGODB URI found in environment.')
    process.exit(1)
  }

  console.log(`Connecting to MongoDB (${isCommit ? 'COMMIT MODE' : 'DRY-RUN MODE'})...`)
  await mongoose.connect(uri)
  const db = mongoose.connection.db

  const authorsCol = db.collection('authors')
  const commentsCol = db.collection('comments')
  const notificationsCol = db.collection('notifications')
  const followsCol = db.collection('follows')
  const poemsCol = db.collection('poems')

  // 1. Locate spam accounts
  const spamAuthors = await authorsCol.find({ username: { $in: TARGET_USERNAMES } }).toArray()
  console.log(`\nFound ${spamAuthors.length} / ${TARGET_USERNAMES.length} target spam accounts:`)
  spamAuthors.forEach(a => {
    console.log(`  - [${a._id}] ${a.username} (${a.email})`)
  })

  if (spamAuthors.length === 0) {
    console.log('No matching spam accounts found in database. Exiting.')
    await mongoose.disconnect()
    return
  }

  const spamIds = spamAuthors.map(a => a._id)
  const spamIdStrings = spamIds.map(id => id.toString())

  // 2. Comments authored or targeted
  const authoredCommentsCount = await commentsCol.countDocuments({ authorId: { $in: spamIds } })
  const targetedCommentsCount = await commentsCol.countDocuments({ targetId: { $in: spamIds } })
  console.log('\nComments to delete:')
  console.log(`  - Authored by spam accounts: ${authoredCommentsCount}`)
  console.log(`  - Targeting spam account profiles: ${targetedCommentsCount}`)

  // 3. Notifications cleanup
  const recipientNotifsCount = await notificationsCol.countDocuments({ recipient: { $in: spamIds } })
  const actorOnlySpamNotifsCount = await notificationsCol.countDocuments({
    actors: { $in: spamIds },
    'actors.1': { $exists: false } // only 1 actor in array
  })
  const multiActorSpamNotifsCount = await notificationsCol.countDocuments({
    actors: { $in: spamIds },
    'actors.1': { $exists: true } // multi-actor notification to be trimmed
  })
  console.log('\nNotifications to clean:')
  console.log(`  - Addressed to spam recipients: ${recipientNotifsCount}`)
  console.log(`  - Sole-actor spam notifications to delete: ${actorOnlySpamNotifsCount}`)
  console.log(`  - Multi-actor notifications to trim (pull spam actor & decrement count): ${multiActorSpamNotifsCount}`)

  // 4. Follows cleanup
  const followsCount = await followsCol.countDocuments({
    $or: [{ follower: { $in: spamIds } }, { following: { $in: spamIds } }]
  })
  console.log(`\nFollow edges to delete: ${followsCount}`)

  // 5. Likes on poems cleanup
  const poemsWithLikesCount = await poemsCol.countDocuments({ likes: { $in: spamIdStrings } })
  console.log(`\nPoems with likes to clean: ${poemsWithLikesCount}`)

  // 6. Authors to delete
  console.log(`\nAuthor documents to delete: ${spamAuthors.length}`)

  // --- EXECUTION IF --commit ---
  if (!isCommit) {
    console.log('\n======================================================')
    console.log('DRY RUN COMPLETE: No changes were written to the DB.')
    console.log('Run with --commit to perform the actual deletion.')
    console.log('======================================================')
  } else {
    console.log('\n>>> EXECUTING DELETIONS AND CLEANUP...')

    // A. Delete comments
    const delCommentsRes = await commentsCol.deleteMany({
      $or: [{ authorId: { $in: spamIds } }, { targetId: { $in: spamIds } }]
    })
    console.log(`Deleted ${delCommentsRes.deletedCount} comments.`)

    // B. Delete sole-actor notifications & recipient notifications
    const delNotifsRes = await notificationsCol.deleteMany({
      $or: [
        { recipient: { $in: spamIds } },
        { actors: { $in: spamIds }, 'actors.1': { $exists: false } }
      ]
    })
    console.log(`Deleted ${delNotifsRes.deletedCount} spam notifications.`)

    // Trim multi-actor notifications if any
    if (multiActorSpamNotifsCount > 0) {
      const trimRes = await notificationsCol.updateMany(
        { actors: { $in: spamIds } },
        {
          $pull: { actors: { $in: spamIds } },
          $inc: { count: -1 }
        }
      )
      console.log(`Trimmed ${trimRes.modifiedCount} multi-actor notifications.`)
    }

    // C. Delete follows
    const delFollowsRes = await followsCol.deleteMany({
      $or: [{ follower: { $in: spamIds } }, { following: { $in: spamIds } }]
    })
    console.log(`Deleted ${delFollowsRes.deletedCount} follows.`)

    // D. Clean likes from poems
    const cleanLikesRes = await poemsCol.updateMany(
      { likes: { $in: spamIdStrings } },
      { $pull: { likes: { $in: spamIdStrings } } }
    )
    console.log(`Cleaned likes from ${cleanLikesRes.modifiedCount} poems.`)

    // E. Delete author records
    const delAuthorsRes = await authorsCol.deleteMany({ _id: { $in: spamIds } })
    console.log(`Deleted ${delAuthorsRes.deletedCount} spam author documents.`)

    console.log('\nSUCCESS: Database spam purge finished completely.')
  }

  await mongoose.disconnect()
}

run().catch(err => {
  console.error('Purge error:', err)
  process.exit(1)
})
